css:
#tongsci1-3-2-1-3-moon .mj-body { grid-template-columns: 1080px minmax(0, 1fr); }
.mj-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #05070f; }
.mj-stage canvas { touch-action: none; cursor: grab; }
.mj-stage canvas.holding { cursor: grabbing; }
.mj-panel { gap: 12px; }
.mj-out { margin: 0; font-size: 21px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.8em; flex: none; }
.mj-out b { color: var(--accent); }
.mj-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 21px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
.mj-tab th { font: 700 20px/1.25 var(--f-body); background: color-mix(in srgb, var(--accent) 12%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 6px; }
.mj-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 8px; text-align: center; height: 38px; font-family: var(--f-mono); }
.mj-tab td:first-child { font-family: var(--f-body); color: var(--ink-2); }
.mj-tab td:empty::after { content: "?"; color: var(--ink-3); opacity: .5; }
.mj-tab tr.new td { background: color-mix(in srgb, var(--hl) 55%, #fff); transition: background .4s; }

